1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit. Readers only ever see committed batches, in
5	// strictly increasing sequence order starting at 1.
6	package log
7	
8	import (
9		"errors"
10		"fmt"
11		"os"
12		"path/filepath"
13		"sort"
14		"strconv"
15		"strings"
16		"sync"
17	)
18	
19	var (
20		// ErrNotCommitted is returned when reading a sequence that has been
21		// staged with Append but not yet committed.
22		ErrNotCommitted = errors.New("log: batch not committed")
23		// ErrUnknownBatch is returned for sequence 0, sequences that were
24		// never reserved, sequences beyond the reserved range, and batches
25		// that have already been committed.
26		ErrUnknownBatch = errors.New("log: unknown batch")
27		// ErrCorruptSegment is returned when a segment file fails validation
28		// while opening or scanning the log.
29		ErrCorruptSegment = errors.New("log: corrupt segment")
30		// ErrInvalidOptions is returned by Open when the options are not
31		// usable, e.g. a non-positive segment capacity.
32		ErrInvalidOptions = errors.New("log: invalid options")
33		// ErrSyncFailed is returned by Commit when Options.Sync is set and
34		// fsyncing the segment file fails. The batch stays staged and keeps
35		// its reserved sequence; committing it again retries.
36		ErrSyncFailed = errors.New("log: sync failed")
37	)
38	
39	var errClosed = errors.New("log: closed")
40	
41	// syncFile fsyncs a segment file. It is a variable so tests can
42	// simulate sync failures.
43	var syncFile = func(f *os.File) error { return f.Sync() }
44	
45	// Options configures a Log opened with Open.
46	type Options struct {
47		// SegmentBytes is the capacity of one segment file in bytes. Once a
48		// non-empty segment would exceed it, the log rolls to a new segment.
49		// A single batch larger than the capacity occupies its own segment.
50		// Must be positive.
51		SegmentBytes int
52		// Sync makes Commit fsync the segment file before returning, so a
53		// returned commit is durable.
54		Sync bool
55	}
56	
57	// Batch is a group of records identified by a single sequence number.
58	// A Batch returned by Append is staged; after Commit it is readable.
59	type Batch struct {
60		seq     uint64
61		records [][]byte
62		owner   *Log
63	}
64	
65	// Seq returns the sequence number reserved for the batch.
66	func (b Batch) Seq() uint64 { return b.seq }
67	
68	// Records returns a copy of the batch's records.
69	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
70	
71	// Segment describes one segment file by the committed sequences it holds.
72	type Segment struct {
73		FirstSeq uint64
74		LastSeq  uint64
75	}
76	
77	// Log is an append-only batch-commit log stored in a directory of
78	// segment files. It is safe for concurrent use, but the writer side is
79	// expected to be a single goroutine (see README Limits).
80	type Log struct {
81		dir  string
82		opts Options
83	
84		mu         sync.Mutex
85		file       *os.File // current segment, nil until first write
86		fileSize   int
87		segIndex   int // index of the current segment file, 0 = none yet
88		curBatches int // committed batches in the current segment
89		nextSeq    uint64
90		staged     map[uint64][][]byte
91		committed  map[uint64][][]byte
92		segs       []Segment // segments holding at least one committed batch
93		closed     bool
94	}
95	
96	// Open opens the log in dir, creating the directory if needed. Existing
97	// segments are validated and their committed batches become readable.
98	// A half-written tail of the last segment — the remnant of a crash
99	// mid-write — is discarded without error and its reserved sequence
100	// stays a permanent hole; any other inconsistency is ErrCorruptSegment.
101	func Open(dir string, opts Options) (*Log, error) {
102		if opts.SegmentBytes <= 0 {
103			return nil, ErrInvalidOptions
104		}
105		if err := os.MkdirAll(dir, 0o755); err != nil {
106			return nil, err
107		}
108		entries, err := os.ReadDir(dir)
109		if err != nil {
110			return nil, err
111		}
112		var indices []int
113		for _, e := range entries {
114			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
115				continue
116			}
117			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
118			if err != nil {
119				continue
120			}
121			indices = append(indices, n)
122		}
123		sort.Ints(indices)
124	
125		l := &Log{
126			dir:       dir,
127			opts:      opts,
128			nextSeq:   1,
129			staged:    make(map[uint64][][]byte),
130			committed: make(map[uint64][][]byte),
131		}
132		for i, n := range indices {
133			data, err := os.ReadFile(l.segmentPath(n))
134			if err != nil {
135				return nil, err
136			}
137			batches, tail, err := parseSegment(data)
138			if err != nil {
139				return nil, err
140			}
141			if tail != nil && i != len(indices)-1 {
142				// A half-written tail is a crash remnant only in the
143				// last segment; anywhere else it is tampering.
144				return nil, ErrCorruptSegment
145			}
146			l.curBatches = len(batches)
147			if len(batches) > 0 {
148				seg := Segment{FirstSeq: ^uint64(0)}
149				for _, pb := range batches {
150					l.committed[pb.seq] = pb.records
151					if pb.seq < seg.FirstSeq {
152						seg.FirstSeq = pb.seq
153					}
154					if pb.seq > seg.LastSeq {
155						seg.LastSeq = pb.seq
156					}
157				}
158				l.segs = append(l.segs, seg)
159				if seg.LastSeq >= l.nextSeq {
160					l.nextSeq = seg.LastSeq + 1
161				}
162			}
163			if tail != nil {
164				// Drop the torn entry so later appends stay parseable, and
165				// keep its reserved sequence as a permanent hole: the
166				// crashed batch stays staged forever and its sequence is
167				// never reused.
168				if err := os.Truncate(l.segmentPath(n), int64(tail.off)); err != nil {
169					return nil, err
170				}
171				if tail.hasSeq && tail.seq > 0 {
172					if _, ok := l.committed[tail.seq]; !ok {
173						l.staged[tail.seq] = nil
174					}
175					if tail.seq >= l.nextSeq {
176						l.nextSeq = tail.seq + 1
177					}
178				}
179			}
180		}
181		if len(indices) > 0 {
182			l.segIndex = indices[len(indices)-1]
183			if err := l.openCurrent(); err != nil {
184				return nil, err
185			}
186		}
187		return l, nil
188	}
189	
190	// Append stages a batch of records and reserves the next sequence number
191	// for it. The batch becomes readable only after Commit.
192	func (l *Log) Append(records [][]byte) (Batch, error) {
193		l.mu.Lock()
194		defer l.mu.Unlock()
195		if l.closed {
196			return Batch{}, errClosed
197		}
198		recs := copyRecords(records)
199		seq := l.nextSeq
200		l.nextSeq++
201		l.staged[seq] = recs
202		return Batch{seq: seq, records: recs, owner: l}, nil
203	}
204	
205	// Commit makes a staged batch durable and readable, and returns its
206	// reserved sequence number. Committing a batch that is not staged —
207	// including one already committed — returns ErrUnknownBatch. With
208	// Options.Sync a returned commit is durable; if the fsync fails Commit
209	// returns ErrSyncFailed and the batch stays staged, keeping its
210	// reserved sequence for a retry.
211	func (l *Log) Commit(b Batch) (uint64, error) {
212		l.mu.Lock()
213		defer l.mu.Unlock()
214		if l.closed {
215			return 0, errClosed
216		}
217		recs, ok := l.staged[b.seq]
218		if !ok || b.owner != l {
219			return 0, ErrUnknownBatch
220		}
221		entry := encodeBatch(b.seq, recs)
222		if err := l.writeEntry(entry); err != nil {
223			return 0, err
224		}
225		if l.opts.Sync {
226			if err := syncFile(l.file); err != nil {
227				// The batch stays staged and keeps its reserved sequence;
228				// a later Commit retries. Drop the un-synced entry so the
229				// retry cannot duplicate it on disk.
230				l.file.Truncate(int64(l.fileSize - len(entry)))
231				l.fileSize -= len(entry)
232				return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
233			}
234		}
235		delete(l.staged, b.seq)
236		l.committed[b.seq] = recs
237		if l.curBatches == 0 {
238			l.segs = append(l.segs, Segment{FirstSeq: b.seq, LastSeq: b.seq})
239		} else {
240			seg := &l.segs[len(l.segs)-1]
241			if b.seq < seg.FirstSeq {
242				seg.FirstSeq = b.seq
243			}
244			if b.seq > seg.LastSeq {
245				seg.LastSeq = b.seq
246			}
247		}
248		l.curBatches++
249		return b.seq, nil
250	}
251	
252	// Read returns the records of the committed batch with the given
253	// sequence. A staged but uncommitted sequence yields ErrNotCommitted;
254	// sequence 0, never-reserved sequences, and sequences beyond the
255	// reserved range yield ErrUnknownBatch.
256	func (l *Log) Read(seq uint64) ([][]byte, error) {
257		l.mu.Lock()
258		defer l.mu.Unlock()
259		if l.closed {
260			return nil, errClosed
261		}
262		if recs, ok := l.committed[seq]; ok {
263			return copyRecords(recs), nil
264		}
265		if _, ok := l.staged[seq]; ok {
266			return nil, ErrNotCommitted
267		}
268		return nil, ErrUnknownBatch
269	}
270	
271	// Scan replays committed batches with sequence >= from in increasing
272	// sequence order, stopping at the first error returned by fn.
273	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
274		l.mu.Lock()
275		if l.closed {
276			l.mu.Unlock()
277			return errClosed
278		}
279		seqs := make([]uint64, 0, len(l.committed))
280		for seq := range l.committed {
281			if seq >= from {
282				seqs = append(seqs, seq)
283			}
284		}
285		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
286		batches := make([]Batch, len(seqs))
287		for i, seq := range seqs {
288			batches[i] = Batch{seq: seq, records: l.committed[seq], owner: l}
289		}
290		l.mu.Unlock()
291		for _, b := range batches {
292			if err := fn(b); err != nil {
293				return err
294			}
295		}
296		return nil
297	}
298	
299	// Segments lists the segments that hold committed batches, in file
300	// order, each with its first and last committed sequence.
301	func (l *Log) Segments() []Segment {
302		l.mu.Lock()
303		defer l.mu.Unlock()
304		out := make([]Segment, len(l.segs))
305		copy(out, l.segs)
306		return out
307	}
308	
309	// Close closes the current segment file. The log must not be used
310	// afterwards.
311	func (l *Log) Close() error {
312		l.mu.Lock()
313		defer l.mu.Unlock()
314		if l.closed {
315			return nil
316		}
317		l.closed = true
318		if l.file != nil {
319			return l.file.Close()
320		}
321		return nil
322	}
323	
324	// writeEntry appends one encoded batch to the current segment, rolling
325	// to a new segment when the current one is non-empty and would exceed
326	// the configured capacity.
327	func (l *Log) writeEntry(entry []byte) error {
328		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
329			if err := l.file.Close(); err != nil {
330				return err
331			}
332			l.file = nil
333			l.segIndex++
334			l.curBatches = 0
335		}
336		if l.file == nil {
337			if l.segIndex == 0 {
338				l.segIndex = 1
339			}
340			if err := l.openCurrent(); err != nil {
341				return err
342			}
343		}
344		n, err := l.file.Write(entry)
345		if err != nil {
346			return err
347		}
348		l.fileSize += n
349		return nil
350	}
351	
352	func (l *Log) openCurrent() error {
353		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
354		if err != nil {
355			return err
356		}
357		st, err := f.Stat()
358		if err != nil {
359			f.Close()
360			return err
361		}
362		l.file = f
363		l.fileSize = int(st.Size())
364		return nil
365	}
366	
367	func (l *Log) segmentPath(index int) string {
368		return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
369	}
370	
371	func copyRecords(records [][]byte) [][]byte {
372		out := make([][]byte, len(records))
373		for i, r := range records {
374			cp := make([]byte, len(r))
375			copy(cp, r)
376			out[i] = cp
377		}
378		return out
379	}
