285			if _, err := log.Open(dir, log.Options{SegmentBytes: 1 << 20}); !errors.Is(err, log.ErrCorruptSegment) {
286				t.Fatalf("Open err = %v, want ErrCorruptSegment", err)
287			}
288		})
289		t.Run("truncated non-last segment", func(t *testing.T) {
290			// Only the last segment may end in a crash tail; a torn
291			// earlier segment is tampering.
292			dir := t.TempDir()
293			l := open(t, dir, log.Options{SegmentBytes: 32})
294			commit(t, l, []byte("one"))
295			commit(t, l, []byte("two"))
296			l.Close()
297	
298			first := filepath.Join(dir, "000001.seg")
299			data, err := os.ReadFile(first)
300			if err != nil {
301				t.Fatal(err)
302			}
303			if err := os.WriteFile(first, data[:len(data)-3], 0o644); err != nil {
304				t.Fatal(err)
305			}
306			if _, err := log.Open(dir, log.Options{SegmentBytes: 32}); !errors.Is(err, log.ErrCorruptSegment) {
307				t.Fatalf("Open err = %v, want ErrCorruptSegment", err)
308			}
309		})
310		t.Run("garbage", func(t *testing.T) {
311			dir := newCorruptLog(t, func(d []byte) []byte { return []byte("not a segment") })
312			if _, err := log.Open(dir, log.Options{SegmentBytes: 1 << 20}); !errors.Is(err, log.ErrCorruptSegment) {
