389	func TestCrashTailRecovery(t *testing.T) {
390		dir := t.TempDir()
391		opts := log.Options{SegmentBytes: 1 << 20}
392	
393		l := open(t, dir, opts)
394		commit(t, l, []byte("one"))
395		commit(t, l, []byte("two"))
396		l.Close()
397	
398		// Power loss halfway through writing batch 3.
399		appendTornEntry(t, dir, 3)
400	
401		l = open(t, dir, opts) // must not fail
402		if got, err := l.Read(1); err != nil || string(got[0]) != "one" {
403			t.Fatalf("Read(1) = %q, %v", got, err)
404		}
405		// The crashed batch stays staged: its sequence is a permanent hole.
406		if _, err := l.Read(3); !errors.Is(err, log.ErrNotCommitted) {
407			t.Fatalf("Read(3) err = %v, want ErrNotCommitted", err)
408		}
409		// The next staged batch gets the hole's sequence plus one.
410		b, err := l.Append([][]byte{[]byte("four")})
411		if err != nil {
412			t.Fatalf("Append: %v", err)
413		}
414		if b.Seq() != 4 {
415			t.Fatalf("seq after crash tail = %d, want 4", b.Seq())
416		}
417		if _, err := l.Commit(b); err != nil {
418			t.Fatalf("Commit: %v", err)
419		}
420		// Replay skips the hole and yields committed batches in order.
421		var seqs []uint64
422		if err := l.Scan(1, func(b log.Batch) error {
423			seqs = append(seqs, b.Seq())
424			return nil
425		}); err != nil {
426			t.Fatalf("Scan: %v", err)
427		}
428		if !reflect.DeepEqual(seqs, []uint64{1, 2, 4}) {
429			t.Fatalf("scan seqs = %v, want [1 2 4]", seqs)
430		}
431		l.Close()
432	
433		// The torn bytes were dropped: after another reopen the log is
434		// consistent and the hole does not come back as a torn entry.
435		l = open(t, dir, opts)
436		var again []uint64
437		if err := l.Scan(1, func(b log.Batch) error {
438			again = append(again, b.Seq())
439			return nil
440		}); err != nil {
441			t.Fatalf("Scan after reopen: %v", err)
442		}
443		if !reflect.DeepEqual(again, []uint64{1, 2, 4}) {
444			t.Fatalf("scan after reopen = %v, want [1 2 4]", again)
445		}
446		if seq := commit(t, l, []byte("five")); seq != 5 {
447			t.Fatalf("seq = %d, want 5", seq)
448		}
449	}
