557	func TestConcurrentReadWrite(t *testing.T) {
558		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
559	
560		const batches = 50
561		done := make(chan struct{})
562		var wg sync.WaitGroup
563		// Concurrent readers and replayers while the writer commits.
564		for g := 0; g < 3; g++ {
565			wg.Add(1)
566			go func() {
567				defer wg.Done()
568				for {
569					select {
570					case <-done:
571						return
572					default:
573					}
574					for seq := uint64(1); seq <= batches; seq++ {
575						got, err := l.Read(seq)
576						if errors.Is(err, log.ErrUnknownBatch) || errors.Is(err, log.ErrNotCommitted) {
577							continue
578						}
579						if err != nil {
580							t.Errorf("Read(%d): %v", seq, err)
581							return
582						}
583						want := []byte(fmt.Sprintf("rec-%d", seq))
584						if len(got) != 1 || !reflect.DeepEqual(got[0], want) {
585							t.Errorf("Read(%d) = %q, want %q", seq, got, want)
586							return
587						}
588					}
589					var prev uint64
590					if err := l.Scan(1, func(b log.Batch) error {
591						if b.Seq() <= prev {
592							t.Errorf("scan out of order: %d after %d", b.Seq(), prev)
593						}
594						prev = b.Seq()
595						return nil
596					}); err != nil {
597						t.Errorf("Scan: %v", err)
598						return
599					}
600				}
601			}()
602		}
603		for i := 1; i <= batches; i++ {
604			commit(t, l, []byte(fmt.Sprintf("rec-%d", i)))
605		}
606		close(done)
607		wg.Wait()
608	}
